UPDATE paciente SET idMedico = #{idMedico}, nombrePaciente = #{nombrePaciente}, apellidosPaciente = #{apellidosPaciente}, fechaNacimiento = #{fechaNacimiento}, genero = #{genero}, peso = #{peso}, estatura = #{estatura}, talla = #{talla}, email = #{email}, telefono = #{telefono}, domicilio = #{domicilio}, fotografia = #{fotografia}
, codigoAcceso = #{codigoAcceso}
, estatus = #{estatus}
WHERE idPaciente = #{idPaciente}

UPDATE paciente
SET fotografia = #{fotografia}
WHERE idPaciente = #{idPaciente}

UPDATE paciente
SET codigoAcceso = #{codigoAcceso}
WHERE idPaciente = #{idPaciente}

UPDATE paciente
SET estatus = 'Inactivo'
WHERE idPaciente = #{idPaciente}

UPDATE cita
SET idMedicoAnterior = idMedico,
    idMedico = #{idMedicoDestino}
WHERE idPaciente = #{idPaciente} AND idMedico = #{idMedicoOrigen}
